SourceCode.Declaration:
/// <summary>
/// submitCounts' answer. ErrorCode on failure: JOURNAL_POSTED, JOURNAL_NOT_FOUND, CLAIM_LOST,
/// CLAIM_EXPIRED, INVALID_REQUEST, NOT_IMPLEMENTED.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDirectSubmitResponse
{
    boolean success;
    str     errorCode;
    str     message;
    int     acceptedLines;

    boolean thirdCountNeeded;
    str passResult;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('AcceptedLines')]
public int parmAcceptedLines(int _value = acceptedLines)
{
    acceptedLines = _value;
    return acceptedLines;
}

/// <summary>
/// Double-blind: the two passes disagree and a third count is needed.
/// </summary>
[DataMemberAttribute('ThirdCountNeeded')]
public boolean parmThirdCountNeeded(boolean _value = thirdCountNeeded)
{
    thirdCountNeeded = _value;
    return thirdCountNeeded;
}

/// <summary>
/// A short, display-only outcome of this pass, written by the server.
/// </summary>
[DataMemberAttribute('PassResult')]
public str parmPassResult(str _value = passResult)
{
    passResult = _value;
    return passResult;
}
